def count_components(grid, color):
    """Count connected components of a color using BFS"""
    height, width = len(grid), len(grid[0])
    visited = set()
    components = []

    def bfs(start_r, start_c):
        q = [(start_r, start_c)]
        visited.add((start_r, start_c))
        component_cells = []

        while q:
            r, c = q.pop(0)
            component_cells.append((r, c))

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < height and 0 <= nc < width and (nr,nc) not in visited and grid[nr][nc] == color:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return component_cells

    for r in range(height):
        for c in range(width):
            if grid[r][c] == color and (r,c) not in visited:
                comps = bfs(r, c)
                components.append(comps)

    return len(components), sum(len(c) for c in components)

def analyze_colors(grid, name):
    print(f"\n{name}:")
    background_color = max(set(cell for row in grid for cell in row), 
                          key=lambda c: sum(cell == c for row in grid for cell in row))
