G = load_grids()

def count_components(grid, color):
    height, width = len(grid), len(grid[0])
    visited = set()
    components = []

    def bfs(start_r, start_c):
        q = [(start_r, start_c)]
        visited.add((start_r, start_c))

        while q:
            r, c = q.pop(0)

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < height and 0 <= nc < width and (nr,nc) not in visited and grid[nr][nc] == color:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return True

    for r in range(height):
        for c in range(width):
            if grid[r][c] == color and (r,c) not in visited:
                bfs(r, c)
                components.append(len([x for x in visited]))

    # Recompute properly
    visited.clear()
    total_cells = 0
    for r in range(height):
        for c in range(width):
            if grid[r][c] == color and (r,c) not in visited:
                visited.add((r,c))
                cells = 1
                q = [(r,c)]
                while q:
                    cr, cc = q.pop(0)
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width and (nr,nc) not in visited and grid[nr][nc] == color:
                            visited.add((nr,nc))
                            q.append((nr,nc))
                    cells += len(q) - sum(len(q) for _ in [0]*cells[-1])
                total_cells += cells

    return len(components), total_cells

# Simpler approach - just use BFS once per component
def count_components_v2(grid, color):
    height, width = len(grid), len(grid[0])
    visited = set()
    component_sizes = []

    for r in range(height):
        for c in range(width):
            if grid[r][c] == color and (r,c) not in visited:
                # Start BFS
                comp_size = 0
                q = [(r,c)]
                visited.add((r,c))

                iterations = 0
                max_iterations = 10**6
                while q and iterations < max_iterations:
                    cr, cc = q.pop(0)
                    comp_size += 1
                    iterations += 1

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width and (nr,nc) not in visited and grid[nr][nc] == color:
                            visited.add((nr,nc))
                            q.append((nr,nc))
                component_sizes.append(comp_size)

    return len(component_sizes), component_sizes

def analyze_colors(grid, name):
    print(f"\n{name}:")
    all_counts = {}
    for row in grid:
        for cell in row:
            all_counts[cell] = all_counts.get(cell, 0) + 1

    background_color = max(all_counts.keys(), key=lambda c: all_counts[c])
    bg_count = all_counts[background_color]
    print(f"  Background color: {background_color} ({bg_count} cells)")

    for c in sorted(all_counts.keys()):
        if c != background_color:
            ncomps, sizes = count_components_v2(grid, c)
            print(f"  Color {c}: {all_counts[c]} cells, {ncomps} components (sizes: {sizes})")

